      "result": "pass",
      "reason": "The memo opens, develops context and work into evidence, and closes as a completed packet with a career invitation."
    },
    "clipart": {
      "result": "pass",
      "reason": "The central object is Rafael’s actual working document rather than a stock emblem of analytics."
    },
    "honesty": {
      "result": "pass",
      "reason": "The final plan preserves corrected metrics, actual contributions, academic project limits, and confidentiality boundaries."
    },
