      "result": "pass",
      "reason": "The first viewport specifies his name, role, concrete reporting result, and immediate Contact link."
    },
    "plain_reader": {
      "result": "pass",
      "reason": "The opening uses plain language about useful dashboards and contextualises the five-hour-to-two-hour reporting improvement."
    }
